payload.arguments:
{"cmd":"cd /Users/vincet/Documents/skills
out=installed_skills_classified.md
{
  echo "# Installed Skills (Classified)"
  echo
  echo "Generated: $(date '+%Y-%m-%d %H:%M:%S %Z')"
  echo
} > "$out"

classify(){
  n="$1"
  case "$n" in
    ios-*|swiftui-*|android-*|macos-*|appkit-*|signing-*|packaging-*|swiftpm-*) echo "Mobile & Apple Dev" ;;
    web-*|frontend-*|react-*|shadcn-*|supabase-*|stripe-*|cloudflare-*|workers-*|wrangler-*) echo "Web & Cloud" ;;
    game-*|phaser-*|three-*|sprite-*|remotion-*|music-*|art-*|imagegen-*|creative-*) echo "Game & Creative" ;;
    github-*|gh-*|circleci-*|code-review-*|repo-*|ci-*|deploy-*|launch-*|release-*|rollback-*|quality-*|qa-*|verification-*|runtime-*|reliability-*|stability-*|risk-*|ops-*|delivery-*|execution-*|automation-*|policy-*|trust-*|guardrail-*|safeguard-*|mission-*|control-*|throughput-*|triage-*|checkpoint-*|baseline-*|anomaly-*|drift-*|fail-*|recovery-*|bottleneck-*|cadence-*|priority-*|objective-*|impact-*|dependency-*|consistency-*|continuity-*|assurance-*|integrity-*|signal-*|stack-*|platform-*|workflow-*|command-*|dispatch-*|evidence-*|knowledge-*|learning-*|outcome-*|frontier-*|capability-*|decision-*|precision-*|confidence-*|variance-*|adaptive-*|action-*|experiment-*|handoff-*|feature-*|foundation-*|product-*|app-*|code-*|coding-*|crossdomain-*|cross-platform-*|fullcycle-*|fullstack-*|engineering-*|design-*|develop-*|discover-*|define-*|deliver-*|measure-*|iterate-*|review-*|standup-*|project-*|exec-*|research-*|utility-*|skill-*) echo "Engineering Process & Ops" ;;
    documents-*|spreadsheets-*|presentations-*|browser-*|chronicle-*|mcp-*|agents-*|ai-agent-*|hardware-*|sandbox-*) echo "Productivity & Agent Tools" ;;
    *) echo "Other" ;;
  esac
}

# collect rows: category|name|desc
rows=$(mktemp)
find . -maxdepth 2 -name SKILL.md | sed 's#^./##' | sort | while read -r p; do
  d=$(awk 'BEGIN{IGNORECASE=1} /^description:/ {sub(/^description:[[:space:]]*/,""); print; exit}' "$p")
  [ -z "$d" ] && d="No description provided"
  n=$(echo "$p" | cut -d/ -f1)
  c=$(classify "$n")
  printf '%s|%s|%s\n' "$c" "$n" "$d"
done > "$rows"

for c in "Engineering Process & Ops" "Game & Creative" "Web & Cloud" "Mobile & Apple Dev" "Productivity & Agent Tools" "Other"; do
  cnt=$(awk -F'|' -v c="$c" '$1==c{n++} END{print n+0}' "$rows")
  [ "$cnt" -eq 0 ] && continue
  {
    echo "## $c ($cnt)"
    echo
    awk -F'|' -v c="$c" '$1==c {printf "- `%s`: %s\n", $2, $3}' "$rows"
    echo
  } >> "$out"
done

rm -f "$rows"

echo "$out""}

